import{buildInfection}from './infection-meshes.js?v=20261023-physicscomplete01';
import{contactNetwork,selectedCohort}from './medicine-models.js?v=20261023-physicscomplete01';
const mat=(T,c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.3,metalness:.04,...e});
function ball(g,T,x,y,z,r,c,scale=[1,1,1],name=''){let m=new T.Mesh(new T.SphereGeometry(r,28,20),mat(T,c));m.position.set(x,y,z);m.scale.set(...scale);m.name=name;g.add(m);return m;}
function rod(g,T,a,b,r,c,name=''){let p=new T.Vector3(...a),q=new T.Vector3(...b),v=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,v.length(),18),mat(T,c));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());m.name=name;g.add(m);return m;}
function antibody(g,T,x,y,z,s=.5){for(let[a,b]of[[[x,y-s,z],[x,y,z]],[[x,y,z],[x-s*.6,y+s*.6,z]],[[x,y,z],[x+s*.6,y+s*.6,z]]])rod(g,T,a,b,s*.09,0xe9aa96,'specific-antibody');}
function bacteria(g,T,x,y,resistant=false,s=.28){let m=new T.Mesh(new T.CapsuleGeometry(s*.4,s*.65,8,20),mat(T,resistant?0xe4b893:0x8bb7b2));m.rotation.z=Math.PI/2;m.position.set(x,y,.2);m.name=resistant?'resistant-cell':'susceptible-cell';g.add(m);if(resistant){let rim=new T.Mesh(new T.TorusGeometry(s*.57,.025,8,24),mat(T,0xf4ddad));rim.position.set(x,y,.35);rim.name='resistance-marker';g.add(rim);}}
export function buildMedicine(g,T,w={}){let kind=w.kind||'memory',s=w.state||'initial',r=w.revealed!==false;
if(kind==='memory'){let antigen=s==='different'?new T.BoxGeometry(.5,.5,.5):new T.SphereGeometry(.32,24,16),m=new T.Mesh(antigen,mat(T,0x8db9b5));m.position.set(0,.7,0);m.name='selected-antigen';g.add(m);let n=r?(s==='repeat'?7:s==='different'?1:3):1;for(let i=0;i<n;i++)antibody(g,T,Math.sin(i*2.4)*1.1,-.3+Math.cos(i*2.4)*.55,.25,.36);if(s!=='initial'){let a=new T.Mesh(new T.TorusGeometry(.6,.055,10,48),mat(T,0xe4c797));a.position.set(0,-1.3,0);a.name='memory-symbol';g.add(a);}}
else if(kind==='network'){let n=contactNetwork(w.coverage??(s==='gaps'?40:80),w.steps??(r?5:0));for(let[a,b]of n.edges){let position=i=>[(i%5-2)*.75,(1.5-Math.floor(i/5))*.75,0];rod(g,T,position(a),position(b),.012,0x68898f,'contact-edge');}for(let i=0;i<20;i++){let x=(i%5-2)*.75,y=(1.5-Math.floor(i/5))*.75,protectedNode=n.protectedNodes.includes(i),infected=n.infected.includes(i);ball(g,T,x,y,0,.16,protectedNode?0xa9c8b9:infected?0xe6a28c:0xbcc9cc,[1,1,1],protectedNode?'protected-node':infected?'infected-node':'susceptible-node');if(protectedNode){let ring=new T.Mesh(new T.TorusGeometry(.23,.026,8,24),mat(T,0xf0d7a8));ring.position.set(x,y,.05);ring.name='protected-ring';g.add(ring);}if(infected)rod(g,T,[x-.05,y-.05,.18],[x+.05,y+.05,.18],.018,0x663f3c,'infection-mark');}}
else if(kind==='selection'){let c=selectedCohort(w.antibiotic!==false,w.step??(s==='before'?0:s==='after'?1:2));for(let i=0;i<c.total;i++)bacteria(g,T,-1.65+(i%8)*.47,1-Math.floor(i/8)*.47,i>=c.susceptible,.28);}
else if(kind==='treatment'||kind==='susceptibility'){if(s==='viral'){buildInfection(g,T,{kind:'replicate',state:'copies',revealed:true});}else{let alive=s==='pain'||s==='ineffective'||!r;for(let i=0;i<(alive?8:0);i++)bacteria(g,T,-1.1+(i%4)*.72,.65-Math.floor(i/4)*.72,false,.45);let height=s==='pain'&&r?.35:1.5;rod(g,T,[-1.8,-1,0],[-1.8,-1+height,0],.09,0xe7b795,'symptom-gauge');if(!alive)for(let i=0;i<5;i++)ball(g,T,-1+i*.5,0,.2,.07,0xc9d4cb,[1,1,1],'removed-fragment');}}
else if(kind==='host'){buildInfection(g,T,{kind:'replicate',state:r&&s==='target'?'entry':'copies',revealed:true});if(s==='target'&&r)for(let child of g.children)if(['virus-core','viral-spike'].includes(child.name))child.position.x-=1.3;if(s==='damage'&&r)for(let i=0;i<5;i++)rod(g,T,[-.8+i*.35,-.8,.8],[-.6+i*.35,.6,.8],.035,0xe39a89,'host-damage-marker');}
else if(kind==='sources'){if(s==='mould'){let dish=new T.Mesh(new T.CylinderGeometry(1.55,1.55,.12,64),mat(T,0xa9c3c4,{transparent:true,opacity:.55}));dish.rotation.x=Math.PI/2;dish.name='petri-dish';g.add(dish);ball(g,T,0,0,.13,.55,0xa5b49e,[1,1,.25],'mould-colony');for(let i=0;i<18;i++){let a=i*Math.PI/9;rod(g,T,[Math.cos(a)*.15,Math.sin(a)*.15,.23],[Math.cos(a)*.65,Math.sin(a)*.65,.23],.025,0xd8d4b2,'hypha');}for(let i=0;i<14;i++){let a=i*Math.PI/7;bacteria(g,T,Math.cos(a)*1.2,Math.sin(a)*1.2,false,.15);}}else if(s==='lab'){let flask=new T.Mesh(new T.SphereGeometry(.9,40,28),mat(T,0xb4d0d1,{transparent:true,opacity:.5}));flask.position.y=-.3;flask.name='synthesis-flask';g.add(flask);rod(g,T,[0,.4,0],[0,1.4,0],.18,0xb4d0d1);ball(g,T,0,-.65,0,.65,0xd4b7a2,[1,.5,1]);for(let i=0;i<4;i++)ball(g,T,Math.sin(i*2)*.4,.1+i*.2,.2,.06,0xf1d6b1);}else{rod(g,T,[0,-1.5,0],[0,1.5,0],.045,0x8fa990,'plant-stem');for(let i=0;i<6;i++){let side=i%2?1:-1,y=-1.1+i*.38;rod(g,T,[0,y,0],[side*.65,y+.35,0],.02,0x8fa990);let leaf=ball(g,T,side*.65,y+.35,0,.38,0x9fb7a0,s==='willow'?[.45,1.3,.12]:[.7,1,.15],'source-leaf');leaf.rotation.z=-side*.6;}if(s==='foxglove')for(let i=0;i<6;i++){let side=i%2?1:-1,m=new T.Mesh(new T.CylinderGeometry(.18,.27,.5,28,1,true),mat(T,0xbc9eb5,{side:T.DoubleSide}));m.position.set(side*.35,.15+i*.23,.3);m.rotation.z=side*.5;m.name='foxglove-flower';g.add(m);}}}
else if(kind==='preclinical'){if(s==='clinical'){buildMedicine(g,T,{kind:'trial'});return;}if(s==='animals'){ball(g,T,0,0,0,.8,0xc3b3ab,[1.5,.65,.65],'animal-model');ball(g,T,1,.2,0,.4,0xd2c3b7);for(let sign of[-1,1])ball(g,T,1.05,.55,sign*.25,.18,0xd7b5ac,[1,1,.3]);rod(g,T,[-1.1,-.1,0],[-1.9,.4,0],.035,0xcfafa2,'tail');}else if(s==='tissues'){for(let j=0;j<3;j++)for(let i=0;i<6;i++)ball(g,T,-1.1+i*.43,-.5+j*.45,(j%2)*.15,.23,0xa9beb7,[1,1,.65],'tissue-cell');}else{let plate=new T.Mesh(new T.BoxGeometry(3,.2,2),mat(T,0xd3c9ba));plate.rotation.x=.5;plate.position.y=-.35;plate.name='culture-plate';g.add(plate);for(let i=0;i<6;i++)ball(g,T,-1+(i%3),-.15+Math.floor(i/3)*.5,.6,.2,0x9bbcb5,[1,.6,1],'culture-cell');}}
else {for(let i=0;i<20;i++){let x=-1.5+(i%5)*.75,y=1.1-Math.floor(i/5)*.65;ball(g,T,x,y,0,.14,i<10?0x91b6b5:0xd0b49e,[1,1,1.2],'trial-participant');rod(g,T,[x,y-.15,0],[x,y-.38,0],.07,i<10?0x91b6b5:0xd0b49e);}for(let i of[-1,1]){let ring=new T.Mesh(new T.TorusGeometry(.23,.04,10,32),mat(T,0xf0d5af));ring.position.set(i*.8,1.65,0);ring.name='coded-group';g.add(ring);}}
}
